  "kind": "map_collision",
  "dimension": 3,
  "map": [
    [
      {"c": 1, "e": [1, 0, 0]}
    ],
    [
      {"c": 1, "e": [0, 1, 0]}
    ],
    [
      {"c": 1, "e": [0, 0, 1]}
    ]
  ],
  "points": [
    [0, 0, 0],
    [1, 0, 0]
  ]
